@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Load initial data during SSR so it appears in the first HTML response.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetAll();
    }

    // OnAfterRenderAsync with firstRender == true fires only when the component
    // is live and interactive on the client — never during static SSR prerender.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
        await base.OnAfterRenderAsync(firstRender);
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Track the highest ID we've already loaded so we only fetch new ones.
        var lastSeenId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            // Simulate external system producing a notification
            NotificationService.SimulateIncoming();

            var newer = NotificationService.GetNewerThan(lastSeenId);
            if (newer.Count > 0)
            {
                // Prepend new notifications (they are already sorted newest-first)
                _notifications.InsertRange(0, newer);
                lastSeenId = _notifications.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

